limitations.witnessSource:
@input input
@a data.get source $input key "a"
@b data.get source $input key "b"
@s number.add left $a right $b
@output number.multiply left $s right $s

demonstrations:
@input input
@context data.get source $input key "context"
@seed bindings.unit
@first relation.join rows $seed facts $context name "step0" arg0 "ask" arg1 "A" arg2 "A"
@second relation.join rows $first facts $context name "step1" arg0 "answer" arg1 "A" arg2 "A"
@output rows.project rows $second name "ack" arg0 "A" arg1 "A"
